import type { BankQuestion } from "@/lib/bank";

/** Fundamental Rights (Indian Polity): 111 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"polity-fundamental-rights-1","question":"Fundamental Rights are contained in which Part of the Constitution?","options":["Part II","Part III","Part IV","Part V"],"answer":1,"explanation":"Part III (Articles 12–35) contains the Fundamental Rights.","difficulty":"easy"},
  {"id":"polity-fundamental-rights-2","question":"How many Fundamental Rights does the Constitution guarantee today?","options":["5","6","7","8"],"answer":1,"explanation":"Six: originally seven, but the Right to Property was removed in 1978.","difficulty":"easy"},
  {"id":"polity-fundamental-rights-3","question":"Dr. B. R. Ambedkar described which Article as the “heart and soul” of the Constitution?","options":["Article 19","Article 21","Article 32","Article 368"],"answer":2,"explanation":"Article 32 (Right to Constitutional Remedies) lets citizens move the Supreme Court directly to enforce Fundamental Rights.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-4","question":"The Right to Education (Article 21A) was inserted by which Amendment?","options":["73rd Amendment","74th Amendment","86th Amendment","93rd Amendment"],"answer":2,"explanation":"The 86th Amendment Act, 2002 inserted Article 21A for free and compulsory education for children aged 6–14.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-5","question":"Fundamental Rights in the Indian Constitution were borrowed from the Constitution of:","options":["UK","USA","Ireland","Canada"],"answer":1,"explanation":"The idea came from the American Bill of Rights.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-6","question":"The Right to Property was removed from the list of Fundamental Rights by the:","options":["42nd Amendment","44th Amendment","52nd Amendment","86th Amendment"],"answer":1,"explanation":"The 44th Amendment (1978) removed it; it is now a constitutional legal right under Article 300A.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-7","question":"Which writ directs a public official to perform a duty they have failed to perform?","options":["Habeas Corpus","Mandamus","Certiorari","Quo Warranto"],"answer":1,"explanation":"Mandamus (“we command”) orders a public authority to do its duty.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-8","question":"The writ of Quo Warranto is issued to:","options":["Release a person from illegal detention","Question the legality of a person holding a public office","Quash the order of a lower court","Stop proceedings in a lower court"],"answer":1,"explanation":"Quo Warranto (“by what authority”) challenges a person’s claim to a public office.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-9","question":"Which Fundamental Right is available to citizens only, not to foreigners?","options":["Article 14","Article 19","Article 21","Article 25"],"answer":1,"explanation":"Article 19 (six freedoms) is for citizens only; Articles 14, 21 and 25 apply to all persons.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-10","question":"Which Fundamental Rights cannot be suspended even during a National Emergency?","options":["Articles 14 and 19","Articles 19 and 32","Articles 20 and 21","Articles 25 and 26"],"answer":2,"explanation":"After the 44th Amendment, Articles 20 and 21 cannot be suspended under Article 359.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-11","question":"Under which Article can Parliament restrict the Fundamental Rights of members of the armed forces?","options":["Article 33","Article 34","Article 35","Article 31"],"answer":0,"explanation":"Article 33 empowers Parliament to modify Fundamental Rights for armed forces, police and intelligence agencies.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-12","question":"Which Article of the Constitution abolishes untouchability?","options":["Article 14","Article 15","Article 17","Article 21"],"answer":2,"explanation":"Article 17 abolishes untouchability and forbids its practice in any form.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"polity-fundamental-rights-13","question":"Which Article is called the “heart and soul of the Constitution” (right to constitutional remedies)?","options":["Article 19","Article 21","Article 32","Article 226"],"answer":2,"explanation":"Ambedkar called Article 32 the heart and soul of the Constitution.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"polity-fundamental-rights-14","question":"The writ issued to a person holding a public office to show by what authority they hold it is:","options":["Habeas corpus","Mandamus","Certiorari","Quo warranto"],"answer":3,"explanation":"Quo warranto means “by what warrant”.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"polity-fundamental-rights-15","question":"The right to property was removed from the Fundamental Rights by the 44th Amendment and placed as a legal right under:","options":["Article 19(1)(f)","Article 31","Article 300A","Article 350"],"answer":2,"explanation":"Since 1978 Article 300A protects property as a constitutional, not fundamental, right.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-16","question":"Consider: 1. Article 15 is available only to citizens. 2. Article 21 is available to citizens and foreigners. 3. Article 19 is suspended automatically during an emergency declared on the ground of war or external aggression. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct. Since the 44th Amendment, Article 358 suspends Article 19 only for war or external aggression, not armed rebellion.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-17","question":"Employment of children below 14 years in factories, mines or other hazardous work is prohibited by:","options":["Article 21A","Article 23","Article 24","Article 39"],"answer":2,"explanation":"Article 24 bans child labour in hazardous jobs; Article 23 bans forced labour and trafficking.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-18","question":"During a National Emergency, the President cannot suspend the right to move courts for the enforcement of:","options":["Articles 14 and 19","Articles 19 and 21","Articles 20 and 21","Articles 21 and 32"],"answer":2,"explanation":"The 44th Amendment (1978) made Articles 20 and 21 non-suspendable under Article 359.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-19","question":"The right to privacy was held to be a fundamental right by a nine-judge bench in:","options":["Maneka Gandhi v Union of India (1978)","Justice K. S. Puttaswamy v Union of India (2017)","A. K. Gopalan v State of Madras (1950)","Kharak Singh v State of UP (1962)"],"answer":1,"explanation":"Puttaswamy (2017) held privacy to be intrinsic to Article 21, overruling the earlier view in M. P. Sharma and Kharak Singh.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-20","question":"How many of these statements are correct? I. Article 14 applies to all persons, including foreigners. II. Article 16 deals with equality of opportunity in public employment. III. Article 18 bars titles but allows military and academic distinctions. IV. Article 17 can be enforced only against the State.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Article 17 (untouchability) applies against private persons too.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-21","question":"How many of these statements are correct? I. Habeas corpus can be issued against private individuals. II. Mandamus can be issued against the President. III. Prohibition can be issued against purely administrative authorities.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I. Mandamus does not lie against the President or a Governor, and prohibition lies only against judicial or quasi-judicial bodies.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-22","question":"How many of these Articles are available to foreigners as well as citizens? I. Article 14 II. Article 15 III. Article 20 IV. Article 29","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only Articles 14 and 20. Article 15 protects citizens only, and Article 29 protects “any section of the citizens”.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-23","question":"How many of these statements are correct? I. Article 32 is itself a fundamental right. II. The writ jurisdiction of High Courts under Article 226 is wider than that of the Supreme Court under Article 32. III. Dr Ambedkar called Article 32 the “heart and soul” of the Constitution.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three. Article 226 is wider because High Courts can issue writs for any legal right, not only fundamental rights.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-24","question":"The “doctrine of eclipse” applies to:","options":["Pre-constitutional laws that are inconsistent with fundamental rights","Post-constitutional laws that violate fundamental rights","Constitutional amendments that violate the basic structure","Ordinances that lapse when Parliament reassembles"],"answer":0,"explanation":"A pre-1950 law that conflicts with a fundamental right is not void but eclipsed; it revives if the right is amended (Bhikaji Narain Dhakras, 1955). Post-constitutional laws that violate fundamental rights are void from the start.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-25","question":"Which pair of writ and its literal meaning is NOT correctly matched?","options":["Habeas corpus – “to have the body”","Mandamus – “we command”","Certiorari – “to be certified”","Quo warranto – “to forbid”"],"answer":3,"explanation":"Quo warranto means “by what authority”; it is prohibition that means “to forbid”.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-26","question":"How many of these statements are correct? I. Article 19 originally guaranteed seven freedoms; the right to property was dropped by the 44th Amendment. II. The safeguards of Article 22 against arrest do not apply to enemy aliens. III. Preventive detention beyond three months needs the opinion of an advisory board. IV. Article 21 can be suspended by a Presidential order under Article 359.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Since the 44th Amendment, Articles 20 and 21 cannot be suspended even during a National Emergency.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-27", "question": "The Right to Freedom of Religion is guaranteed by which Articles of the Constitution?", "options": ["Articles 19 to 22", "Articles 23 and 24", "Articles 25 to 28", "Articles 29 and 30"], "answer": 2, "explanation": "Articles 25–28 cover freedom of conscience, management of religious affairs, freedom from religious taxes and freedom from religious instruction in state institutions. Articles 29–30 are the Cultural and Educational Rights.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-fundamental-rights-28", "question": "Protection against double jeopardy and against being compelled to be a witness against oneself is given by:", "options": ["Article 20", "Article 21", "Article 22", "Article 19"], "answer": 0, "explanation": "Article 20 gives three protections in respect of conviction for offences: no ex post facto law, no double jeopardy and no self-incrimination. Article 22 deals with arrest and detention.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-fundamental-rights-29", "question": "The Cultural and Educational Rights of minorities are contained in:", "options": ["Articles 14 and 15", "Articles 23 and 24", "Articles 25 and 26", "Articles 29 and 30"], "answer": 3, "explanation": "Article 29 protects the language, script and culture of any section of citizens, and Article 30 gives minorities the right to establish and administer educational institutions.", "difficulty": "easy", "source": "SSC CGL · UPSSSC PET"},
  {"id": "polity-fundamental-rights-30", "question": "Under which clause of Article 15 can the State make special provisions for women and children?", "options": ["Article 15(2)", "Article 15(5)", "Article 15(4)", "Article 15(3)"], "answer": 3, "explanation": "Article 15(3) allows special provisions for women and children. Article 15(4) (added in 1951) covers socially and educationally backward classes, SCs and STs, and 15(5) their admission to private educational institutions.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-31", "question": "Which provision permits reservation of posts in favour of a backward class of citizens that is not adequately represented in state services?", "options": ["Article 16(1)", "Article 16(2)", "Article 16(4)", "Article 16(3)"], "answer": 2, "explanation": "Article 16(4) enables reservation in appointments for any backward class not adequately represented in the services. Article 16(3) lets Parliament prescribe residence as a condition for certain posts.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-32", "question": "Article 23 prohibits traffic in human beings and begar, but it expressly allows the State to:", "options": ["Employ children in non-hazardous work", "Impose compulsory service for public purposes without discrimination", "Permit bonded labour in agriculture", "Levy a tax in place of military service"], "answer": 1, "explanation": "Article 23(2) lets the State impose compulsory service for public purposes (such as military or social service) provided it does not discriminate on grounds of religion, race, caste or class.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-33", "question": "Article 30 gives the right to establish and administer educational institutions to:", "options": ["All citizens", "Religious and linguistic minorities", "Scheduled Castes and Scheduled Tribes", "Only religious minorities"], "answer": 1, "explanation": "Article 30(1) confers the right on all minorities, whether based on religion or language. It is a group right that is not available to the majority community.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-34", "question": "Which of these is NOT a ground on which the State may impose reasonable restrictions on freedom of speech under Article 19(2)?", "options": ["Sovereignty and integrity of India", "Contempt of court", "Defamation", "Economic interests of the State"], "answer": 3, "explanation": "Article 19(2) lists sovereignty and integrity, security of the State, friendly relations with foreign states, public order, decency or morality, contempt of court, defamation and incitement to an offence. Economic interests are not a ground.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-35", "question": "Article 13 declares laws inconsistent with Fundamental Rights void “to the extent of such inconsistency”. The doctrine that follows from these words is the doctrine of:", "options": ["Eclipse", "Severability", "Waiver", "Pith and substance"], "answer": 1, "explanation": "Under the doctrine of severability only the offending part of a law is struck down, if it can be separated from the rest. The doctrine of eclipse applies to pre-constitutional laws that become dormant, not dead.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-36", "question": "Which Amendment added clause (4) to Article 13, declaring that a constitutional amendment under Article 368 is not “law” for the purposes of Article 13?", "options": ["1st Amendment, 1951", "24th Amendment, 1971", "25th Amendment, 1971", "42nd Amendment, 1976"], "answer": 1, "explanation": "After Golaknath (1967) held that Parliament could not amend Fundamental Rights, the 24th Amendment added Article 13(4) and Article 368(3) to restore the amending power. The 25th Amendment inserted Article 31C.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-37", "question": "Article 15(5), which allows reservation for socially and educationally backward classes in private unaided educational institutions other than minority institutions, was inserted by the:", "options": ["85th Amendment, 2001", "86th Amendment, 2002", "93rd Amendment, 2005", "97th Amendment, 2011"], "answer": 2, "explanation": "The 93rd Amendment (2005) added Article 15(5) after the Supreme Court’s decision in P. A. Inamdar; it excludes minority institutions under Article 30(1). The 86th Amendment added Article 21A.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-38", "question": "The 10% reservation for Economically Weaker Sections was added through Articles 15(6) and 16(6) by the:", "options": ["102nd Amendment, 2018", "103rd Amendment, 2019", "104th Amendment, 2019", "101st Amendment, 2016"], "answer": 1, "explanation": "The 103rd Amendment (2019) inserted Articles 15(6) and 16(6); it was upheld by a 3:2 majority in Janhit Abhiyan v. Union of India (2022). The 102nd Amendment gave constitutional status to the National Commission for Backward Classes.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-39", "question": "Before Article 21A was inserted in 2002, the Supreme Court had already read a right to education for children up to 14 years into Article 21 in:", "options": ["Vishaka v. State of Rajasthan (1997)", "Maneka Gandhi v. Union of India (1978)", "Olga Tellis v. Bombay Municipal Corporation (1985)", "Unni Krishnan v. State of Andhra Pradesh (1993)"], "answer": 3, "explanation": "In Unni Krishnan (1993), building on Mohini Jain (1992), the Court held that the right to education up to 14 years flows from Article 21 read with Article 45. Olga Tellis dealt with the right to livelihood and Vishaka with sexual harassment at work.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-40", "question": "The 44th Amendment (1978) reduced the period for which a person can be preventively detained without the opinion of an advisory board from three months to two months. What is the status of this change?", "options": ["It is in force since 1979", "It was struck down by the Supreme Court", "It has never been brought into force, so the three-month period still applies", "It applies only to detention under central laws"], "answer": 2, "explanation": "Section 3 of the 44th Amendment Act, which amended Article 22, was never notified by the government, so the original three-month limit continues to operate.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-41", "question": "The narrow interpretation of “procedure established by law” in A. K. Gopalan (1950) was overturned, requiring the procedure under Article 21 to be just, fair and reasonable, in:", "options": ["Kharak Singh v. State of U.P. (1962)", "Sunil Batra v. Delhi Administration (1978)", "ADM Jabalpur v. Shivkant Shukla (1976)", "Maneka Gandhi v. Union of India (1978)"], "answer": 3, "explanation": "Maneka Gandhi (1978) read Articles 14, 19 and 21 together and introduced American-style due process into Article 21. ADM Jabalpur (the Habeas Corpus case) had, in contrast, denied relief during the Emergency.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-42", "question": "The right to form co-operative societies was added to Article 19(1)(c) by the:", "options": ["73rd Amendment, 1992", "86th Amendment, 2002", "97th Amendment, 2011", "99th Amendment, 2014"], "answer": 2, "explanation": "The 97th Amendment (2011) added “co-operative societies” to Article 19(1)(c), inserted Article 43B in the Directive Principles and added Part IX-B on co-operative societies.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-43", "question": "Under Article 32(3), the power to issue writs for the enforcement of Fundamental Rights can be conferred on any other court by:", "options": ["The President by order", "Parliament by law", "The Supreme Court by rules", "The Chief Justice of India"], "answer": 1, "explanation": "Article 32(3) empowers Parliament, by law, to authorise any other court to exercise the Supreme Court’s writ powers without prejudice to the Supreme Court’s own jurisdiction. No such law has yet been made.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-44", "question": "The protection against ex post facto laws in Article 20(1) does NOT extend to:", "options": ["Imposing a penalty greater than that prescribed when the offence was committed", "Conviction for an act that was not an offence when committed", "Civil liabilities and retrospective tax laws", "Punishment for a criminal offence under a retrospective law"], "answer": 2, "explanation": "Article 20(1) applies only to criminal convictions and punishments. Civil legislation and tax laws can operate retrospectively, as can preventive detention, which is not a punishment for an offence.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-45", "question": "How many of these statements about Article 19 are correct? I. Article 19 today guarantees six freedoms. II. The freedom to acquire, hold and dispose of property under Article 19(1)(f) was deleted by the 44th Amendment. III. The ground “sovereignty and integrity of India” in Article 19(2) was added by the 16th Amendment, 1963. IV. The rights under Article 19 are available to companies registered in India.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Article 19 rights are available only to citizens, and the Supreme Court has held that a company, not being a citizen, cannot claim them, though its shareholders can.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-46", "question": "Assertion (A): The rights under Articles 20 and 21 cannot be suspended even during a National Emergency. Reason (R): The 44th Amendment, 1978 amended Article 359 to exclude Articles 20 and 21 from any Presidential order suspending the enforcement of Fundamental Rights.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "After the Emergency experience and ADM Jabalpur, the 44th Amendment made Articles 20 and 21 immune from suspension under Article 359; R is exactly why A holds.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-47", "question": "Arrange these Supreme Court cases in chronological order: 1. Maneka Gandhi 2. A. K. Gopalan 3. K. S. Puttaswamy 4. Kesavananda Bharati", "options": ["2, 4, 1, 3", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "A. K. Gopalan (1950), Kesavananda Bharati (1973), Maneka Gandhi (1978) and Puttaswamy (2017).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-48", "question": "Which pair of Article and its subject is NOT correctly matched?", "options": ["Article 16 – Equality of opportunity in public employment", "Article 18 – Abolition of untouchability", "Article 23 – Prohibition of traffic in human beings and forced labour", "Article 28 – Freedom from religious instruction in institutions wholly maintained by State funds"], "answer": 1, "explanation": "Article 18 abolishes titles; untouchability is abolished by Article 17.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-fundamental-rights-49", "question": "How many of these statements about Articles 25 to 28 are correct? I. Article 25 (freedom of conscience) is available to all persons, not only citizens. II. Article 26 gives rights to religious denominations as groups. III. Article 27 says no person shall be compelled to pay taxes for the promotion of any particular religion. IV. Article 28 bars religious instruction in institutions wholly maintained out of State funds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Note the distinction in Article 27: a tax for promoting a religion is barred, but a fee for regulating religious institutions is permissible.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-50", "question": "How many of these statements about reservation-related Amendments are correct? I. The 77th Amendment (1995) added Article 16(4A) allowing reservation in promotions for SCs and STs. II. The 81st Amendment (2000) added Article 16(4B) allowing unfilled reserved vacancies to be carried forward. III. The 85th Amendment (2001) introduced the “creamy layer” concept into Article 16. IV. The 103rd Amendment (2019) added Articles 15(6) and 16(6) for Economically Weaker Sections.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The 85th Amendment gave consequential seniority in promotion; the creamy layer idea came from the Supreme Court (Indra Sawhney, 1992), not from an amendment.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-51", "question": "Assertion (A): Some Fundamental Rights can be enforced against private individuals and not only against the State. Reason (R): Articles 15(2), 17, 23 and 24 are worded so as to apply against private persons as well.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Most Fundamental Rights run against the State, but access to shops and public places (15(2)), untouchability (17), forced labour (23) and child labour (24) are enforceable against private persons too.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-52", "question": "How many of these statements about writs are correct? I. Habeas corpus will not be issued when the detention is lawful. II. Mandamus cannot be issued to enforce a private contractual obligation. III. Certiorari, originally confined to judicial and quasi-judicial bodies, has been available against administrative authorities since 1991. IV. Quo warranto can be issued in respect of a private office.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Quo warranto lies only against a substantive public office created by a statute or the Constitution, never a private office.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-53", "question": "Arrange these Constitutional Amendments in chronological order: 1. 44th Amendment (right to property removed) 2. 86th Amendment (right to education) 3. 24th Amendment (Article 13(4) added) 4. 93rd Amendment (Article 15(5) added)", "options": ["3, 1, 2, 4", "1, 3, 2, 4", "3, 1, 4, 2", "1, 3, 4, 2"], "answer": 0, "explanation": "24th (1971), 44th (1978), 86th (2002) and 93rd (2005).", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-54", "question": "How many of these have been held by the Supreme Court to be part of the right to life under Article 21? I. Right to sleep II. Right to die with dignity, including passive euthanasia III. Right to privacy IV. Right to property", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Ramlila Maidan, 2012), II (Common Cause, 2018) and III (Puttaswamy, 2017) are part of Article 21. The right to property is only a constitutional/legal right under Article 300A since 1978.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-55", "question": "Which of these is NOT a Fundamental Right under Article 19?", "options": ["Right to form associations or unions", "Right to strike", "Right to move freely throughout the territory of India", "Right to reside and settle in any part of India"], "answer": 1, "explanation": "The Supreme Court has repeatedly held that the right to strike is not a fundamental right; it is only a legal right regulated by industrial law, and does not flow from the right to form unions under Article 19(1)(c).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-56", "question": "Assertion (A): Article 15(4), permitting special provisions for socially and educationally backward classes, was added by the 1st Amendment, 1951. Reason (R): It was Parliament’s response to the Supreme Court striking down caste-based reservation in State of Madras v. Champakam Dorairajan.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In Champakam Dorairajan (1951) the Court struck down the Madras Communal G.O. as violating Article 15(1); the 1st Amendment then inserted Article 15(4) to permit such provisions.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-57", "question": "Article 21A obliges the State to provide free and compulsory education to all children in the age group of:", "options": ["3 to 10 years", "5 to 15 years", "6 to 14 years", "6 to 18 years"], "answer": 2, "explanation": "Article 21A, inserted by the 86th Amendment (2002), covers children aged six to fourteen; the Right of Children to Free and Compulsory Education Act, 2009 gives it effect.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-58", "question": "Which Article defines the term “State” for the purposes of Part III (Fundamental Rights)?", "options": ["Article 12", "Article 13", "Article 36", "Article 14"], "answer": 0, "explanation": "Article 12 defines “State” to include the Government and Parliament of India, State governments and legislatures, and all local or other authorities. Article 36 applies the same meaning to Part IV.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-59", "question": "Under Article 22(2), a person arrested and detained must be produced before the nearest magistrate within:", "options": ["12 hours", "24 hours, excluding the time of the journey", "48 hours, including the time of the journey", "72 hours"], "answer": 1, "explanation": "Article 22(2) fixes 24 hours, excluding the time needed for the journey from the place of arrest to the court. No further detention is allowed without the magistrate’s authority.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-60", "question": "The freedom to reside and settle in any part of the territory of India is guaranteed by:", "options": ["Article 19(1)(b)", "Article 19(1)(d)", "Article 19(1)(g)", "Article 19(1)(e)"], "answer": 3, "explanation": "Article 19(1)(e) is the freedom to reside and settle; 19(1)(d) is the separate freedom to move freely throughout India; 19(1)(b) is to assemble peaceably and 19(1)(g) is to practise any profession or trade.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-61", "question": "The Ninth Schedule, which shields the laws placed in it from challenge on the ground of violating Fundamental Rights, was added along with Article 31B by the:", "options": ["1st Amendment, 1951", "4th Amendment, 1955", "17th Amendment, 1964", "25th Amendment, 1971"], "answer": 0, "explanation": "The 1st Amendment (1951) created Article 31B and the Ninth Schedule to protect land reform laws. In I. R. Coelho (2007) the Court held that laws added after 24 April 1973 can still be tested against the basic structure.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-62", "question": "Article 29(1), which protects the right to conserve a distinct language, script or culture, is available to:", "options": ["Only religious minorities", "Only linguistic minorities", "Any section of citizens having a distinct language, script or culture", "All persons residing in India"], "answer": 2, "explanation": "Article 29(1) speaks of “any section of the citizens”, so it is not confined to minorities, unlike Article 30. Being limited to citizens, it does not extend to foreigners.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-63", "question": "Explanation I to Article 25 states that the wearing and carrying of which of these shall be deemed to be included in the profession of the Sikh religion?", "options": ["Kara", "Kirpan", "Kesh", "Kangha"], "answer": 1, "explanation": "Explanation I to Article 25 expressly protects the wearing and carrying of kirpans by Sikhs. The other articles of faith are not mentioned in the text.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-64", "question": "Under Article 16(3), a residence requirement within a State for appointment to certain posts under that State can be prescribed only by:", "options": ["The State Legislature", "The Governor", "Parliament", "The State Public Service Commission"], "answer": 2, "explanation": "Article 16(3) allows only Parliament to prescribe residence as a condition for employment in a State; Article 35 reinforces that such laws are for Parliament alone, not State legislatures.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-65", "question": "Under Article 35, the power to make laws to give effect to provisions such as Articles 16(3), 32(3), 33 and 34 is vested in:", "options": ["Parliament only", "State Legislatures only", "Both Parliament and State Legislatures", "The President by order"], "answer": 0, "explanation": "Article 35 gives this power exclusively to Parliament so that there is uniformity across India; State legislatures cannot legislate on these matters.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-66", "question": "Article 34 allows Parliament, by law, to indemnify any government servant for acts done to restore order in an area where:", "options": ["A National Emergency is in force", "Martial law was in force", "President’s Rule is in force", "An area is declared disturbed under AFSPA"], "answer": 1, "explanation": "Article 34 deals with restriction of rights while martial law is in force, and lets Parliament indemnify acts done in connection with it. The Constitution does not define martial law.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-67", "question": "In Indra Sawhney v. Union of India (1992), the Supreme Court upheld 27% reservation for OBCs subject to which conditions?", "options": ["Exclusion of the creamy layer and an overall ceiling of 50%", "Reservation in promotions and no ceiling", "A 60% ceiling and inclusion of economic criteria alone", "Reservation only for Hindu backward classes"], "answer": 0, "explanation": "The nine-judge bench required the creamy layer to be excluded, set a normal 50% ceiling and held that Article 16(4) does not permit reservation in promotions (later restored for SCs/STs by the 77th Amendment).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-68", "question": "The right to a speedy trial was first recognised as part of Article 21 in:", "options": ["Hussainara Khatoon v. State of Bihar (1979)", "Olga Tellis v. Bombay Municipal Corporation (1985)", "Maneka Gandhi v. Union of India (1978)", "Sunil Batra v. Delhi Administration (1978)"], "answer": 0, "explanation": "Hussainara Khatoon, a PIL on undertrial prisoners in Bihar, held speedy trial to be implicit in Article 21. Olga Tellis concerned pavement dwellers and the right to livelihood.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-69", "question": "The Supreme Court held that the right to livelihood is part of the right to life under Article 21 in a case brought by pavement dwellers of Bombay. The case is:", "options": ["M. C. Mehta v. Union of India", "Olga Tellis v. Bombay Municipal Corporation", "Vishaka v. State of Rajasthan", "Francis Coralie Mullin v. Administrator, Delhi"], "answer": 1, "explanation": "Olga Tellis (1985) held that eviction deprives a person of livelihood and therefore engages Article 21, though it allowed eviction after fair procedure. Vishaka (1997) laid down guidelines on sexual harassment at work.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-70", "question": "Which of these has been held by the Supreme Court NOT to be “State” under Article 12?", "options": ["Life Insurance Corporation of India", "Oil and Natural Gas Corporation", "A municipal corporation", "Board of Control for Cricket in India (BCCI)"], "answer": 3, "explanation": "In Zee Telefilms v. Union of India (2005) the Court held the BCCI is not “State” since it is not financially, functionally or administratively controlled by the government; it remains subject to writs under Article 226 for public functions. Statutory corporations such as LIC and ONGC are State.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-71", "question": "Match the case with what it decided: A. Shreya Singhal (2015) B. Navtej Singh Johar (2018) C. Selvi v. State of Karnataka (2010) D. Shayara Bano (2017). 1. Instant triple talaq is unconstitutional 2. Section 66A of the IT Act struck down 3. Consensual same-sex relations between adults decriminalised 4. Involuntary narco-analysis violates Article 20(3)", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-3, C-4, D-1", "A-4, B-3, C-2, D-1"], "answer": 2, "explanation": "Shreya Singhal struck down Section 66A as violating Article 19(1)(a); Navtej Johar read down Section 377 IPC; Selvi held compulsory narco tests violate the right against self-incrimination; Shayara Bano invalidated talaq-e-biddat.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-72", "question": "How many of these statements about Article 22 are correct? I. An arrested person must be informed of the grounds of arrest as soon as may be. II. An arrested person has the right to consult and be defended by a legal practitioner of choice. III. An arrested person must be produced before a magistrate within 24 hours. IV. These three safeguards apply equally to a person held under a preventive detention law.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct under Article 22(1) and (2). IV is wrong: Article 22(3) expressly excludes enemy aliens and persons under preventive detention from these safeguards; detainees get the separate protections of 22(4)–(7).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-73", "question": "Assertion (A): The freedoms under Article 19 are automatically suspended when a National Emergency is proclaimed on the ground of armed rebellion. Reason (R): After the 44th Amendment, Article 358 suspends Article 19 only when the Emergency is declared on the ground of war or external aggression.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Since 1978, Article 358 applies only to an external Emergency (war or external aggression); an Emergency on the ground of armed rebellion does not automatically suspend Article 19.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-74", "question": "Arrange these cases on Parliament’s power to amend Fundamental Rights in chronological order: 1. Golaknath 2. Shankari Prasad 3. Sajjan Singh 4. Kesavananda Bharati", "options": ["2, 1, 3, 4", "2, 3, 1, 4", "3, 2, 1, 4", "2, 3, 4, 1"], "answer": 1, "explanation": "Shankari Prasad (1951) and Sajjan Singh (1965) upheld Parliament’s power to amend Fundamental Rights; Golaknath (1967) denied it; Kesavananda Bharati (1973) restored it subject to the basic structure.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-75", "question": "How many of these statements about Article 30 are correct? I. Minority status for Article 30 is determined State-wise, as held in T. M. A. Pai Foundation (2002). II. Article 30(1A), on compensation when the property of a minority institution is acquired, was added by the 44th Amendment. III. The State cannot discriminate against a minority institution while granting aid. IV. Article 30 protects every educational institution run by any group of citizens.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Article 30(2) bars discrimination in aid). IV is wrong: Article 30 protects only institutions of religious and linguistic minorities.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-76", "question": "How many of these are grounds on which reasonable restrictions may be imposed on freedom of speech and expression under Article 19(2)? I. Contempt of court II. Defamation III. Friendly relations with foreign States IV. Interests of the general public", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are grounds in Article 19(2). “Interests of the general public” is a ground for restricting the freedoms of movement, residence and profession under Articles 19(5) and 19(6), not speech.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-77", "question": "How many of these statements about Article 17 are correct? I. The Untouchability (Offences) Act, 1955 was renamed the Protection of Civil Rights Act in 1976. II. The Constitution does not define “untouchability”. III. The SC and ST (Prevention of Atrocities) Act was enacted in 1989. IV. The right under Article 17 is absolute and not subject to any exception.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Article 17 abolishes untouchability and forbids its practice in any form, without exceptions, and leaves the term undefined; Parliament has enforced it through the 1955 (renamed 1976) and 1989 Acts.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-78", "question": "How many of these statements about Articles 15 and 16 are correct? I. Article 15(1) bars discrimination on grounds only of religion, race, caste, sex or place of birth. II. Article 16(2) additionally lists descent and residence as forbidden grounds in public employment. III. Article 15(2) applies to access to shops, hotels and places of public entertainment, even when privately owned. IV. Article 16(5) permits an office connected with a religious institution to be reserved for members of that religion.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Descent and residence appear in Article 16(2) but not in Article 15(1), a frequent trap; 15(2) binds private persons too.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-79", "question": "Assertion (A): The protection against double jeopardy under Article 20(2) does not bar departmental proceedings after a criminal prosecution for the same act. Reason (R): Article 20(2) applies only where the person has been prosecuted and punished before a court or judicial tribunal.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. As held in Maqbool Hussain (1953), departmental or administrative proceedings are not prosecution and punishment by a court, so Article 20(2) does not apply to them.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-80", "question": "Arrange these insertions into Part III in chronological order: 1. Article 15(4) for backward classes 2. Article 16(4A) for reservation in promotions 3. The right to form co-operative societies in Article 19(1)(c) 4. Article 21A", "options": ["1, 2, 4, 3", "1, 4, 2, 3", "2, 1, 4, 3", "1, 2, 3, 4"], "answer": 0, "explanation": "Article 15(4): 1st Amendment, 1951. Article 16(4A): 77th Amendment, 1995. Article 21A: 86th Amendment, 2002. Co-operative societies: 97th Amendment, 2011.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-81", "question": "Which of these Fundamental Rights is available ONLY to citizens and not to foreigners?", "options": ["Article 20 – protection in respect of conviction for offences", "Article 22 – protection against arbitrary arrest", "Article 25 – freedom of religion", "Article 16 – equality of opportunity in public employment"], "answer": 3, "explanation": "Articles 15, 16, 19, 29 and 30 are confined to citizens. Articles 20, 21, 22 and 25 extend to all persons, though Article 22’s safeguards do not apply to enemy aliens.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-82", "question": "The phrase \"equal protection of the laws\" in Article 14 is drawn from the Constitution of:", "options": ["Britain", "USA", "Ireland", "Canada"], "answer": 1, "explanation": "Article 14 combines \"equality before the law\", a British idea (a negative concept: no special privileges), with \"equal protection of the laws\", taken from the 14th Amendment of the US Constitution (a positive concept: like treatment in like circumstances).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-83", "question": "The right to vote in elections to the Lok Sabha and State Assemblies is a:", "options": ["Fundamental Right under Article 19", "Fundamental Right under Article 21", "Fundamental Duty under Article 51A", "Constitutional and statutory right, not a Fundamental Right"], "answer": 3, "explanation": "Article 326 provides for adult suffrage, and the details are in the Representation of the People Act, 1951. Voting is therefore a constitutional and statutory right, not a Fundamental Right, as the Supreme Court has held several times (for example in Kuldip Nayar, 2006).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-84", "question": "Freedom of the press is not mentioned in so many words in the Constitution. The Supreme Court has held it to be part of:", "options": ["Article 19(1)(a)", "Article 14", "Article 19(1)(g)", "Article 21"], "answer": 0, "explanation": "Freedom of the press is implied in the freedom of speech and expression under Article 19(1)(a), as the Court held from Romesh Thappar and Brij Bhushan (1950) onwards. Article 19(1)(g), the freedom of trade or business, is the tempting wrong option.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-85", "question": "Under Explanation II to Article 25, the reference to \"Hindus\" in Article 25(2)(b) includes persons professing which religions?", "options": ["Sikh and Parsi", "Sikh, Jaina or Buddhist", "Jaina and Parsi", "Buddhist and Christian"], "answer": 1, "explanation": "Explanation II says the reference to Hindus includes persons professing the Sikh, Jaina or Buddhist religion, and that Hindu religious institutions are to be read the same way. This matters for laws throwing open Hindu religious institutions to all classes.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-86", "question": "Article 19(1)(b) guarantees citizens the right to assemble. Which two conditions are written into the clause itself?", "options": ["Peaceably and without arms", "With police permission and in daylight", "In public places and with prior notice", "Without arms and for lawful purposes only"], "answer": 0, "explanation": "The clause reads \"to assemble peaceably and without arms\". Other limits, such as public order and the sovereignty and integrity of India, come through Article 19(3), not through the clause itself.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-87", "question": "The concept of \"rule of law\", which is reflected in \"equality before the law\" in Article 14, was propounded by:", "options": ["Ivor Jennings", "Ernest Barker", "K. C. Wheare", "A. V. Dicey"], "answer": 3, "explanation": "A. V. Dicey set out the rule of law with three parts: no arbitrary power, equality before the law, and the primacy of individual rights. The Supreme Court has held the rule of law to be a basic feature of the Constitution.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-88", "question": "The Vishaka guidelines (1997) on sexual harassment of women at the workplace, based on Articles 14, 15, 19(1)(g) and 21, were later replaced by a law passed in:", "options": ["2005", "2013", "2010", "2019"], "answer": 1, "explanation": "The Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 (the POSH Act) gave statutory form to the Vishaka guidelines, including Internal Complaints Committees.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-89", "question": "In Bijoe Emmanuel v. State of Kerala (1986), the Supreme Court protected schoolchildren who stood respectfully but did not sing the National Anthem because of their faith. Their right was upheld under:", "options": ["Articles 14 and 16", "Articles 21 and 21A", "Articles 19(1)(a) and 25", "Articles 29 and 30"], "answer": 2, "explanation": "The Court held that the freedom of speech in Article 19(1)(a) includes the freedom to remain silent, and that expelling the Jehovah's Witness children also violated their freedom of religion under Article 25.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-90", "question": "In National Legal Services Authority v. Union of India (2014), the Supreme Court:", "options": ["Recognised transgender persons as a \"third gender\" with fundamental rights", "Decriminalised consensual same-sex relations", "Struck down instant triple talaq", "Declared privacy a fundamental right"], "answer": 0, "explanation": "NALSA (2014) recognised transgender persons as a third gender entitled to rights under Articles 14, 15, 16, 19 and 21. Section 377 was read down in Navtej Singh Johar (2018), and privacy came in Puttaswamy (2017).", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-91", "question": "Under Article 18(3), a person who is NOT a citizen of India but holds an office of profit or trust under the State can accept a title from a foreign State only with the consent of:", "options": ["The Prime Minister", "Parliament", "The President", "The Ministry of External Affairs"], "answer": 2, "explanation": "Article 18(2) flatly bars citizens from accepting foreign titles. Article 18(3) lets a non-citizen holding an office of profit or trust under the State accept one only with the President's consent, and Article 18(4) applies the same rule to presents and emoluments.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-92", "question": "The Supreme Court upheld freedom of the press against a ban on a journal's entry into Madras State in a 1950 case, which led Parliament to add \"public order\" to Article 19(2) through the 1st Amendment. The case is:", "options": ["A. K. Gopalan v. State of Madras", "Romesh Thappar v. State of Madras", "State of Madras v. Champakam Dorairajan", "Kharak Singh v. State of U.P."], "answer": 1, "explanation": "In Romesh Thappar (1950) the ban on the journal \"Cross Roads\" was struck down because \"public order\" was not then a ground in Article 19(2). The 1st Amendment (1951) added public order, friendly relations with foreign States and incitement to an offence. Champakam Dorairajan led to Article 15(4).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-93", "question": "Which judgment first held that \"equality is antithetic to arbitrariness\", giving Article 14 a meaning beyond reasonable classification?", "options": ["State of West Bengal v. Anwar Ali Sarkar (1952)", "R. C. Cooper v. Union of India (1970)", "Indra Sawhney v. Union of India (1992)", "E. P. Royappa v. State of Tamil Nadu (1974)"], "answer": 3, "explanation": "In E. P. Royappa (1974), Justice Bhagwati wrote that equality and arbitrariness are sworn enemies, so an arbitrary act violates Article 14. Anwar Ali Sarkar (1952) applied the older test of reasonable classification.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-94", "question": "In People's Union for Democratic Rights v. Union of India (1982), about workers on the Asiad construction projects, the Supreme Court held that:", "options": ["Contract labour is barred by Article 24", "Paying a worker less than the minimum wage amounts to forced labour under Article 23", "Construction workers must be given land under Article 39(b)", "Article 23 applies only against the State"], "answer": 1, "explanation": "The Court held that labour given for less than the minimum wage is \"forced labour\" banned by Article 23, since economic need is a form of compulsion. Article 23 also applies against private persons.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-95", "question": "Article 28(1) bars religious instruction in institutions wholly maintained out of State funds. Under Article 28(2), this bar does NOT apply to an institution that:", "options": ["Is run by a religious minority", "Gets a State grant of less than half its expenses", "Is administered by the State but was set up under an endowment or trust that requires religious instruction", "Is a university set up by a State Act"], "answer": 2, "explanation": "Article 28(2) exempts institutions administered by the State but established under an endowment or trust requiring religious instruction. Under Article 28(3), State-recognised or State-aided institutions may give such instruction, but nobody can be made to attend without consent (or a guardian's consent for a minor).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-96", "question": "In Union of India v. Naveen Jindal (2004), the Supreme Court held that the right of a citizen to fly the National Flag with respect and dignity is part of:", "options": ["Article 21", "Article 51A(a) only, and is not enforceable", "Article 25", "Article 19(1)(a)"], "answer": 3, "explanation": "The Court treated flying the flag as an expression of allegiance and pride covered by Article 19(1)(a), subject to reasonable restrictions such as the Flag Code and the Prevention of Insults to National Honour Act, 1971.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-97", "question": "The right of a poor prisoner to free legal aid, including help to file an appeal, was read into Article 21 in:", "options": ["M. H. Hoskot v. State of Maharashtra (1978)", "D. K. Basu v. State of West Bengal (1997)", "Sunil Batra v. Delhi Administration (1978)", "A. K. Gopalan v. State of Madras (1950)"], "answer": 0, "explanation": "M. H. Hoskot (1978) held that free legal aid for an indigent prisoner is part of the fair procedure Article 21 requires, which Article 39A later reinforced. D. K. Basu laid down guidelines on arrest and custody.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-98", "question": "In Ajay Hasia v. Khalid Mujib (1981), the Supreme Court set out tests for deciding when a body is an \"instrumentality or agency of the State\" and so \"State\" under Article 12. On these tests it held which body to be \"State\"?", "options": ["A private cricket club", "A society running a regional engineering college", "A registered political party", "A private trust running a temple"], "answer": 1, "explanation": "The Court held the society that ran the Regional Engineering College, Srinagar to be State, because of deep government funding and control. The tests are government share capital, financial aid, deep and pervasive control, and public functions.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-99", "question": "Which clause of Article 16 permits a law requiring that the holder of an office connected with a religious or denominational institution belong to that religion?", "options": ["Article 16(2)", "Article 16(3)", "Article 16(5)", "Article 16(4B)"], "answer": 2, "explanation": "Article 16(5) saves such laws from the guarantee of equal opportunity. Article 16(3) concerns residence requirements, and Article 16(4B) lets unfilled reserved vacancies be carried forward.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-100", "question": "Under Article 13(3)(a), \"law\" includes several things. How many of these are covered? I. Ordinance II. Bye-law III. Custom or usage having the force of law IV. An amendment of the Constitution made under Article 368", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Article 13(3)(a) defines law to include any ordinance, order, bye-law, rule, regulation, notification, and custom or usage having the force of law. A constitutional amendment is excluded by Article 13(4), inserted by the 24th Amendment (1971).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-101", "question": "Under Article 33, Parliament may restrict or abrogate Fundamental Rights to ensure discipline and the proper discharge of duties. How many of these groups does it cover? I. Members of the armed forces II. Members of forces charged with maintaining public order III. Persons employed in bureaus set up by the State for intelligence or counter-intelligence IV. Persons employed in telecommunication systems set up for such forces or bureaus", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are covered. Groups III and IV were added to Article 33 by the 50th Amendment (1984). Only Parliament, not a State legislature, can make such a law.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-102", "question": "Match the case with what it decided: A. Bachan Singh v. State of Punjab (1980) B. Bandhua Mukti Morcha v. Union of India (1984) C. Kaushal Kishor v. State of U.P. (2023) D. Shirur Mutt case (1954). 1. Laid the basis of the \"essential religious practices\" test 2. Death penalty only in the \"rarest of rare\" cases 3. Identifying and releasing bonded labourers 4. Rights under Articles 19 and 21 can be enforced against persons other than the State", "options": ["A-2, B-3, C-4, D-1", "A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "Bachan Singh upheld the death penalty but limited it to the rarest of rare cases. Bandhua Mukti Morcha was a PIL on bonded labour under Articles 21 and 23. Kaushal Kishor (a Constitution Bench) held that Articles 19 and 21 can apply horizontally. The Shirur Mutt case (1954) held that Article 26 protects what is essential to a religion.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-103", "question": "Arrange these judgments in chronological order: 1. Anuradha Bhasin v. Union of India (internet shutdowns in Jammu and Kashmir) 2. Kharak Singh v. State of U.P. (night-time domiciliary visits) 3. Satwant Singh Sawhney (right to travel abroad) 4. Shreya Singhal v. Union of India (Section 66A of the IT Act)", "options": ["3, 2, 4, 1", "2, 3, 1, 4", "2, 4, 3, 1", "2, 3, 4, 1"], "answer": 3, "explanation": "Kharak Singh 1962 → Satwant Singh Sawhney 1967 → Shreya Singhal 2015 → Anuradha Bhasin 2020. Anuradha Bhasin held that speech and trade over the internet are protected under Articles 19(1)(a) and 19(1)(g), and that indefinite suspension of the internet is not permissible.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-104", "question": "Assertion (A): A citizen cannot waive a Fundamental Right, even of their own free will. Reason (R): Fundamental Rights are not only for the benefit of the individual; they rest on public policy, as the Supreme Court held in Basheshar Nath v. CIT (1959).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In Basheshar Nath (1959) the Court held that the rights in Part III, at least Article 14, are put there as a matter of public policy, so an individual cannot give them up by agreement or settlement. R gives the reason for A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-105", "question": "How many of these statements about the right to education are correct? I. The Right of Children to Free and Compulsory Education Act, 2009 came into force on 1 April 2010. II. Section 12(1)(c) of the Act requires private unaided schools to admit at least 25% of the entry class from weaker and disadvantaged groups. III. In Pramati Educational and Cultural Trust (2014), the Act was held not to apply to minority schools, aided or unaided. IV. Article 21A was inserted by the 93rd Amendment.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Article 21A was inserted by the 86th Amendment (2002). The 93rd Amendment (2005) inserted Article 15(5) on reservation in educational institutions.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-106", "question": "How many of these statements about Indian Young Lawyers Association v. State of Kerala (2018), the Sabarimala case, are correct? I. By a 4:1 majority it struck down the exclusion of women aged 10 to 50 from the temple. II. The lone dissent came from Justice Indu Malhotra. III. The majority held that Ayyappa devotees form a separate religious denomination under Article 26. IV. All four majority judges based their decision on Article 17 (untouchability).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. The majority held that Ayyappa devotees are NOT a separate denomination; Justice Malhotra, dissenting, held that they are. Only Justice Chandrachud treated the exclusion as a form of untouchability under Article 17.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-107", "question": "Article 19(5) allows reasonable restrictions on the freedom to move freely and to reside and settle in any part of India in the interests of the general public. What other ground does it name?", "options": ["Friendly relations with foreign States", "Maintenance of essential supplies", "Decency or morality", "Protection of the interests of any Scheduled Tribe"], "answer": 3, "explanation": "Article 19(5) names two grounds: the interests of the general public and the protection of the interests of any Scheduled Tribe. The second one supports Inner Line Permits and limits on outsiders settling in tribal areas. Friendly relations and decency are grounds under Article 19(2) for speech.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-108", "question": "How many of these statements about Public Interest Litigation are correct? I. In S. P. Gupta v. Union of India (1981), the Supreme Court relaxed the rule of locus standi. II. Letters and postcards sent to judges have been treated as writ petitions (epistolary jurisdiction). III. A PIL can be filed in a High Court under Article 226 as well as in the Supreme Court under Article 32. IV. Article 32(2) expressly mentions public interest litigation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. PIL is a creation of the judges. The Constitution nowhere uses the phrase, and Article 32(2) only lists the writs (habeas corpus, mandamus, prohibition, quo warranto and certiorari) and directions or orders.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-109", "question": "How many of these statements about preventive detention are correct? I. Only Parliament can make a law on preventive detention for reasons of defence, foreign affairs or the security of India. II. Parliament and the State legislatures can both legislate on preventive detention for the security of a State, public order or essential supplies and services. III. Article 22(7) empowers Parliament to prescribe the maximum period of detention. IV. The grounds of detention must be communicated, though facts against the public interest may be withheld.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. I is Entry 9 of the Union List and II is Entry 3 of the Concurrent List. III is Article 22(7)(b), and IV comes from Articles 22(5) and 22(6).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-110", "question": "Assertion (A): A minority educational institution that receives aid from the State cannot refuse admission to a student only because the student belongs to another religion. Reason (R): Article 29(2) forbids denying admission to a State-maintained or State-aided institution on grounds only of religion, race, caste or language.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Article 29(2) binds aided minority institutions too, so R explains A. The Court has still let such institutions give reasonable preference to their own community (St. Stephen's College, 1992), without shutting out others.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-111", "question": "Which pair of a \"saving\" Article and the Amendment that inserted it is NOT correctly matched?", "options": ["Article 31D – 4th Amendment, 1955", "Article 31A – 1st Amendment, 1951", "Article 31B – 1st Amendment, 1951", "Article 31C – 25th Amendment, 1971"], "answer": 0, "explanation": "Article 31D, which saved laws against \"anti-national activities\", was inserted by the 42nd Amendment (1976) and repealed by the 43rd (1977). The 4th Amendment (1955) only amended Article 31A and added laws to the Ninth Schedule.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
];

export default questions;
